//! Visual regression: compare pdf-x rendering against mutool reference goldens.
//!
//! Goldens are generated by `scripts/generate_goldens.py` (renders each test
//! PDF page with `mutool draw`). They are NOT committed (machine-specific
//! anti-aliasing). Generate locally before running:
//!
//! ```sh
//! python3 scripts/generate_goldens.py
//! cargo test --test visual_diff --features "rendering crypto"
//! ```
//!
//! Tolerance: pixels within `MAX_PIXEL_DIFF` of the reference are considered
//! matching (accounts for anti-aliasing differences between tiny-skia and MuPDF).

#![cfg(feature = "rendering")]

use std::fs;
use std::path::PathBuf;

use pdf_x_core::core::PDFDocument;
use pdf_x_device_tinyskia::RenderToImage;

/// Per-channel tolerance for anti-aliasing differences.
const MAX_PIXEL_DIFF: u8 = 15;
/// Minimum match percentage to pass (allows minor anti-aliasing variance).
const MIN_MATCH_PCT: f64 = 97.0;

struct VisualCase {
    pdf: &'static str,
    page: usize,
}

/// Curated subset covering: fonts, paths, images, clipping, text rendering modes.
/// Full corpus (265 PDFs) is tested by `scripts/visual_diff.py`.
static SMOKE_TESTS: &[VisualCase] = &[
    // Fonts
    VisualCase {
        pdf: "font_type1_1",
        page: 0,
    },
    VisualCase {
        pdf: "font_type1_3",
        page: 0,
    },
    VisualCase {
        pdf: "font_truetype_1",
        page: 0,
    },
    VisualCase {
        pdf: "font_truetype_4",
        page: 0,
    },
    VisualCase {
        pdf: "fonts_type1_latex",
        page: 0,
    },
    VisualCase {
        pdf: "font_cid_2",
        page: 0,
    },
    // Paths
    VisualCase {
        pdf: "path_rendering_3",
        page: 0,
    },
    VisualCase {
        pdf: "path_rendering_13",
        page: 0,
    },
    VisualCase {
        pdf: "fillrule_evenodd",
        page: 0,
    },
    // Images
    VisualCase {
        pdf: "image_luma8",
        page: 0,
    },
    VisualCase {
        pdf: "image_rgb8",
        page: 0,
    },
    VisualCase {
        pdf: "image_mask",
        page: 0,
    },
    // Clipping
    VisualCase {
        pdf: "clip_path_evenodd",
        page: 0,
    },
    VisualCase {
        pdf: "clip_path_nested",
        page: 0,
    },
    // Text rendering modes
    VisualCase {
        pdf: "text_rendering_1",
        page: 0,
    },
    VisualCase {
        pdf: "text_rendering_clipping",
        page: 0,
    },
    // XObjects
    VisualCase {
        pdf: "xobject_matrix",
        page: 0,
    },
    // Color spaces
    VisualCase {
        pdf: "color_separation_3",
        page: 0,
    },
    VisualCase {
        pdf: "devicen_none",
        page: 0,
    },
    // Encryption
    VisualCase {
        pdf: "encrypted_aes_128",
        page: 0,
    },
    VisualCase {
        pdf: "encrypted_rc4_rev2",
        page: 0,
    },
];

fn workspace_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .to_path_buf()
}

fn goldens_dir() -> PathBuf {
    workspace_root().join("tests").join("goldens")
}

fn hayro_pdfs_dir() -> PathBuf {
    workspace_root()
        .join("hayro")
        .join("hayro-tests")
        .join("pdfs")
        .join("custom")
}

fn golden_path(name: &str, page: usize, multi_page: bool) -> PathBuf {
    let suffix = if multi_page {
        format!("_p{page}")
    } else {
        String::new()
    };
    goldens_dir().join(format!("{name}{suffix}.png"))
}

/// Compare two RGBA buffers. Returns (matching_pixels, total_compared, max_diff).
fn compare(a: &[u8], aw: u32, ah: u32, b: &[u8], bw: u32, bh: u32) -> (usize, usize, u8) {
    let w = aw.min(bw) as usize;
    let h = ah.min(bh) as usize;
    let mut matching = 0usize;
    let mut total = 0usize;
    let mut max_diff = 0u8;

    for y in 0..h {
        for x in 0..w {
            let ai = (y * aw as usize + x) * 4;
            let bi = (y * bw as usize + x) * 4;
            if ai + 3 >= a.len() || bi + 3 >= b.len() {
                continue;
            }
            total += 1;
            let dr = (a[ai] as i16 - b[bi] as i16).unsigned_abs() as u8;
            let dg = (a[ai + 1] as i16 - b[bi + 1] as i16).unsigned_abs() as u8;
            let db = (a[ai + 2] as i16 - b[bi + 2] as i16).unsigned_abs() as u8;
            let d = dr.max(dg).max(db);
            max_diff = max_diff.max(d);
            if d <= MAX_PIXEL_DIFF {
                matching += 1;
            }
        }
    }
    (matching, total, max_diff)
}

fn load_png_rgba(path: &PathBuf) -> Option<(u32, u32, Vec<u8>)> {
    let data = fs::read(path).ok()?;
    let img = image::load_from_memory(&data).ok()?.into_rgba8();
    let (w, h) = (img.width(), img.height());
    Some((w, h, img.into_raw()))
}

#[test]
fn visual_diff_smoke() {
    let pdfs_dir = hayro_pdfs_dir();
    let goldens = goldens_dir();

    if !goldens.exists() {
        eprintln!(
            "\n[visual_diff] No goldens found at {}. Run: python3 scripts/generate_goldens.py",
            goldens.display()
        );
        eprintln!("[visual_diff] Skipping test.");
        return;
    }

    let mut pass = 0usize;
    let mut fail = 0usize;
    let mut skip = 0usize;
    let mut results = Vec::new();

    for case in SMOKE_TESTS {
        let pdf_path = pdfs_dir.join(format!("{}.pdf", case.pdf));
        if !pdf_path.exists() {
            skip += 1;
            continue;
        }

        // Determine if multi-page golden exists
        let multi = golden_path(case.pdf, case.page, true).exists();
        let golden_path = golden_path(case.pdf, case.page, multi);

        let golden = match load_png_rgba(&golden_path) {
            Some(g) => g,
            None => {
                skip += 1;
                results.push(format!("  {:<30} SKIP (no golden)", case.pdf));
                continue;
            }
        };

        // Render with pdf-x
        let data = match fs::read(&pdf_path) {
            Ok(d) => d,
            Err(_) => {
                skip += 1;
                continue;
            }
        };
        let mut doc = match PDFDocument::open(data) {
            Ok(d) => d,
            Err(_) => {
                skip += 1;
                continue;
            }
        };
        let (pw, ph, pixels) = match doc.render_page_to_image(case.page, Some(1.0)) {
            Ok(r) => r,
            Err(_) => {
                skip += 1;
                continue;
            }
        };

        let (matching, total, max_diff) = compare(&pixels, pw, ph, &golden.2, golden.0, golden.1);
        let pct = if total > 0 {
            matching as f64 / total as f64 * 100.0
        } else {
            0.0
        };
        let status = if pct >= MIN_MATCH_PCT { "PASS" } else { "FAIL" };

        if pct >= MIN_MATCH_PCT {
            pass += 1;
        } else {
            fail += 1;
        }

        results.push(format!(
            "  {:<30} {:4}  {:5.1}% match  maxdiff={:3}",
            case.pdf, status, pct, max_diff
        ));
    }

    eprintln!("\n{}", "=".repeat(60));
    eprintln!("Visual Diff: {} PASS, {} FAIL, {} SKIP", pass, fail, skip);
    eprintln!("{}", "=".repeat(60));
    for line in &results {
        eprintln!("{line}");
    }

    // Don't fail CI for rendering differences — this is a diagnostic test.
    // Uncomment the assert below once rendering quality is high enough.
    // assert_eq!(fail, 0, "{} visual diff failures", fail);
    let _ = (pass, fail, skip);
}
